                // main cone (8-sided so stripe rings read smooth-ish), standing point-up
                addCylinder(root, hat, 0.0, 0.42, H, [0, H / 2 + 0.02, 0], 10); // cone via tapered cylinder for ring stripes
                // stripe rings wrapping the cone at a few heights (thin flat discs)
                const rings = [[0.34, 0.18], [0.24, 0.44], [0.14, 0.7]];
                for (let i = 0; i < rings.length; i += 1) {
                    const r = rings[i][0], y = rings[i][1];
                    addCylinder(root, stripe, r + 0.015, r + 0.015, 0.07, [0, y + 0.02, 0], 10);
                }
                // little brim disc at the base
                addCylinder(root, makeMaterial(shadeColor("#3b8fe0", -0.2)), 0.44, 0.44, 0.05, [0, 0.03, 0], 10);
