                    const m = makeMaterial(color);
                    const segs = 8;
                    for (let i = 0; i < segs; i += 1) {
                        const t = i / segs;
                        const ang = dir * t * 7; // twist as it rises
                        const x = baseX + Math.cos(ang) * 0.14 * dir;
                        const z = baseZ + Math.sin(ang) * 0.14;
                        const y = 0.06 + t * 0.9;
                        addBox(root, m, [0.1, 0.14, 0.02], [x, y, z], [0, ang, 0.4 * dir]);
                    }
