                const starPale = new THREE.MeshStandardMaterial({ color: "#fff2a0", emissive: "#ffe86a", emissiveIntensity: 0.85, flatShading: true, metalness: 0, roughness: 0.4 });
                const rockDark = makeMaterial(shadeColor("#3a3320", -0.1));
