                addCylinder(root, stoneMat, 0.2, 0.22, 2.0, [0, 1.24, 0], 12);
                // shallow flutes: thin recessed boxes ringing the shaft
                for (let i = 0; i < 6; i++) {
                    const a = (i / 6) * Math.PI * 2;
                    addBox(root, stoneDark, [0.05, 1.9, 0.05], [Math.sin(a) * 0.19, 1.24, Math.cos(a) * 0.19], [0, -a, 0]);
                }
                addCylinder(root, stoneMat, 0.24, 0.2, 0.12, [0, 2.3, 0], 12);
                addBox(root, stoneMat, [0.56, 0.12, 0.56], [0, 2.42, 0]);
