                addCylinder(root, bandMat, 0.405, 0.405, 0.08, [0, 0.24, 0], 12); // lower hoop
                addCylinder(root, bandMat, 0.408, 0.408, 0.08, [0, 0.45, 0], 12); // middle hoop
