                addBox(root, plasterMat, [1.5, 0.24, 0.16], [0, 0.14, 0]); // sill row below
                addBox(root, plasterMat, [0.34, 1.5, 0.16], [-0.58, 0.75, 0]); // left jamb
                addBox(root, plasterMat, [0.34, 1.5, 0.16], [0.58, 0.75, 0]); // right jamb
