            root.add(head);
            addSphere(head, body, 0.3, [0, 0, 0]);
            addEyes(head, star, 0.05, -0.24);
            addCone(head, ring, 0.05, 0.2, [-0.12, 0.28, 0]);
            addCone(head, ring, 0.05, 0.2, [0.12, 0.28, 0]);
            // segmented body along +Z, tapering (mixed rows -> tuple cast)
            const segData = [
                [0.68, -0.55, 0.28],
                [0.72, -0.1, 0.26],
                [0.68, 0.35, 0.24],
                [0.62, 0.8, 0.2],
                [0.58, 1.2, 0.16]
            ];
            const segments = [];
            for (let i = 0; i < segData.length; i++) {
                const d = segData[i];
                const seg = new THREE.Group();
                seg.position.set(0, d[0], d[1]);
                root.add(seg);
                addSphere(seg, body, d[2], [0, 0, 0]);
                addSphere(seg, ring, d[2] * 0.55, [0, d[2] * 0.9, 0]);
                segments.push(seg);
            }
            addSphere(root, star, 0.05, [0.3, 0.9, -0.4]);
            parts.head = head;
            parts.segments = segments;
            return { kind: "serpent", parts, root };
