            addBox(clawL, plateMat, [0.16, 0.2, 0.14], [0, -0.1, 0.28]); // club
            const clawR = new THREE.Group();
            clawR.position.set(0.3, 0.42, -0.35);
            root.add(clawR);
            addCylinder(clawR, clawMat, 0.06, 0.08, 0.3, [0, 0, 0.1], 6);
            addBox(clawR, plateMat, [0.16, 0.2, 0.14], [0, -0.1, 0.28]);
            fins.push(clawL, clawR);
